const r=await tools.exec_command({cmd:"python - <<'PY'
import csv,base64,zlib,math
from pathlib import Path
import numpy as np
csv.field_size_limit(2**31-1)
rows=[]
with open('/tmp/ioai-final-buffered.csv',newline='') as f:
 for row in csv.DictReader(f):
  vals=[]
  for c in ('delta_a','delta_b'):
   a=np.frombuffer(zlib.decompress(base64.b64decode(row[c])),dtype='<f4')
   vals.append((float(np.sqrt(np.mean(a*a))),float(np.linalg.norm(a)/a.size),len(a)))
  rows.append((row['id'],vals))
for typ in [0,1]:
 print('TYPE',typ,'mean rms',sum(x[1][typ][0] for x in rows)/len(rows))
 for x in sorted(rows,key=lambda x:x[1][typ][1],reverse=True)[:15]: print(x[0],*[round(v,8) for v in x[1][typ]])
PY",workdir:".",yield_time_ms:30000,max_output_tokens:10000});
