  ids.append(row['id']); s,i=row['id'].split('_'); split='test_leaderboard_a' if s=='a' else 'test_leaderboard_b'
  with Image.open(root/split/'images'/f'{int(i):04d}.png') as im: shape=(3,im.height,im.width); n=np.prod(shape)
  pair=0.0
  for c in ('delta_a','delta_b'):
   raw=zlib.decompress(base64.b64decode(row[c])); assert len(raw)==n*4
   a=np.frombuffer(raw,dtype='<f4'); assert np.isfinite(a).all(); pair += np.linalg.norm(a.astype(np.float64))/n
  by[s].append(pair)
exp=[f'a_{i}' for i in range(100)]+[f'b_{i}' for i in range(100)]; print('rows',len(ids),'order',ids==exp)
for s,v in by.items():
 x=float(np.mean(v)); score=100*(1.5-1/(1+math.exp(-50000*x))); print(s,x,score,round(score,2))
PY"],
 ["clock","date -u"]
];
